request.query:
query Plan($arriveBy: Boolean, $banned: InputBanned, $bikeReluctance: Float, $carReluctance: Float, $date: String, $fromPlace: String!, $modes: [TransportMode], $numItineraries: Int, $preferred: InputPreferred, $time: String, $toPlace: String!, $unpreferred: InputUnpreferred, $walkReluctance: Float, $walkSpeed: Float
  $searchWindow: Long
  $maxStopCount: Int
  $bikeSpeed: Float
  $waitReluctance: Float
  $transferPenalty: Int
  $minTransferTime: Int
  $maxTransfers: Int
  $via: [PlanViaLocationInput!]
  $walkBoardCost: Int, $wheelchair: Boolean) {
  plan(
    arriveBy: $arriveBy
    banned: $banned
    bikeReluctance: $bikeReluctance
    carReluctance: $carReluctance
    date: $date
    fromPlace: $fromPlace
    locale: "en"
    numItineraries: $numItineraries
    preferred: $preferred
    time: $time
    toPlace: $toPlace
    transportModes: $modes
    unpreferred: $unpreferred
    walkReluctance: $walkReluctance
    walkSpeed: $walkSpeed
    searchWindow: $searchWindow
    maxStopCount: $maxStopCount
    bikeSpeed: $bikeSpeed
    waitReluctance: $waitReluctance
    transferPenalty: $transferPenalty
    minTransferTime: $minTransferTime
    maxTransfers: $maxTransfers
    via: $via
    walkBoardCost: $walkBoardCost
    wheelchair: $wheelchair
  ) {
    itineraries {
      accessibilityScore
      duration
      endTime
      legs {
        accessibilityScore
        agency {
          alerts {
            alertDescriptionText
            alertHeaderText
            alertUrl
            effectiveStartDate
            id
          }
          gtfsId
          id: gtfsId
          name
          timezone
          url
        }
        alerts {
          alertDescriptionText
          alertHeaderText
          alertUrl
          effectiveStartDate
          id
        }
        arrivalDelay
        departureDelay
        distance
        dropOffBookingInfo {
          contactInfo {
            bookingUrl
            infoUrl
            phoneNumber
          }
          earliestBookingTime {
            daysPrior
            time
          }
          latestBookingTime {
            daysPrior
            time
          }
          message
        }
        dropoffType
        duration
        endTime
        fareProducts {
          id
          product {
            __typename
            id
            medium {
              id
              name
            }
            name
            riderCategory {
              id
              name
            }
            ... on DefaultFareProduct {
              price {
                amount
                currency {
                  code
                  digits
                }
              }
            }
            ... on DependentFareProduct {
              dependencies {
                id
              }
              price {
                amount
                currency {
                  code
                }
              }
            }
          }
        }
        from {
          lat
          lon
          name
          rentalVehicle {
            id
            network
          }
          stop {
            alerts {
              alertDescriptionText
              alertHeaderText
              alertUrl
              effectiveStartDate
              id
            }
            code
            gtfsId
            id
            lat
            lon
          }
          vertexType
        }
        headsign
        id
        interlineWithPreviousLeg
        intermediateStops {
          lat
          locationType
          lon
          name
          stopCode: code
          stopId: id
        }
        intermediatePlaces {
          arrivalTime
          departureTime
          lat
          lon
          name
          stop {
            code
            gtfsId
            id
          }
        }
        legGeometry {
          length
          points
        }
        mode
        pickupBookingInfo {
          contactInfo {
            bookingUrl
            infoUrl
            phoneNumber
          }
          earliestBookingTime {
            daysPrior
            time
          }
          latestBookingTime {
            daysPrior
            time
          }
          message
        }
        pickupType
        realTime
        realtimeState
        rentedBike
        rideHailingEstimate {
          arrival
          maxPrice {
            amount
            currency {
              code
            }
          }
          minPrice {
            amount
            currency {
              code
            }
          }
          provider {
            id
          }
        }
        route {
          alerts {
            alertDescriptionText
            alertHeaderText
            alertUrl
            effectiveStartDate
            id
          }
          color
          gtfsId
          id: gtfsId
          longName
          shortName
          textColor
          type
        }
        startTime
        steps {
          absoluteDirection
          alerts {
            alertDescriptionText
            alertHeaderText
            alertUrl
            effectiveStartDate
            id
          }
          area
          distance
          elevationProfile {
            distance
            elevation
          }
          lat
          lon
          relativeDirection
          stayOn
          streetName
        }
        stopCalls {
          stopLocation {
            __typename
          }
        }
        to {
          lat
          lon
          name
          rentalVehicle {
            id
            network
          }
          stop {
            alerts {
              alertDescriptionText
              alertHeaderText
              alertUrl
              effectiveStartDate
              id
            }
            code
            gtfsId
            id
            lat
            lon
          }
          vertexType
        }
        transitLeg
        trip {
          arrivalStoptime {
            stop {
              gtfsId
              id
            }
            stopPosition
          }
          departureStoptime {
            stop {
              gtfsId
              id
            }
            stopPosition
          }
          gtfsId
          id
        }
      }
      startTime
      transfers: numberOfTransfers
      waitingTime
      walkTime
    }
    routingErrors {
      code
      description
      inputField
    }
  }
}
